def fib_sum(n: int) -> int:
    if n <= 0:
        return 0
    a, b = 1, 1
    total = a + b if n >= 2 else a
    for _ in range(3, n + 1):
        a, b = b, a + b
        total += b
    return total


def main() -> None:
    result = fib_sum(20)
    print(result)
    print(result)


