MOD = 1_000_000_007


def mat_mult(a, b):
    c = [[0, 0, 0] for _ in range(3)]
    for i in range(3):
        ai = a[i]
        ci = c[i]
        for k in range(3):
            aik = ai[k]
            if aik:
                bk = b[k]
                for j in range(3):
                    ci[j] = (ci[j] + aik * bk[j]) % MOD
    return c


def mat_pow(m, e):
    result = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    base = m
    while e:
        if e & 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        e >>= 1
    return result


def count_strings(n):
    if n == 0:
        return 1 % MOD

    # States: 0 = no matching suffix, 1 = suffix "1", 2 = suffix "10".
    # Appending 1 from state 2 would form "101" and is forbidden.
    transition = [
        [1, 0, 1],
        [1, 1, 0],
        [0, 1, 0],
    ]

    powered = mat_pow(transition, n)
    # Start vector is [1, 0, 0]^T, so the answer is the sum of the first column.
    return (powered[0][0] + powered[1][0] + powered[2][0]) % MOD


def main():
    n1 = 1000000000000000000
    n2 = 987654321987654321
    print(count_strings(n1))
    print(count_strings(n2))


if __name__ == "__main__":
    main()

