module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (Json, decode, getString, getInt, getStringArrayOrEmpty)
import std/list (length as listLength)
import std/string (chars)
import std/option (Some, None)
import std/result (Result, Ok, Err)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: [string]
}

pure func countDotChars(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => (if c == "." then 1 else 0) + countDotChars(rest)
  }

pure func countDots(s: string) -> int =
  countDotChars(chars(s))

pure func validateConfig(obj: Json) -> Result[Config, string] =
  match getString(obj, "app_name") {
    None => Err("missing app_name"),
    Some(appName) => match getString(obj, "version") {
      None => Err("missing version"),
      Some(version) => match getInt(obj, "port") {
        None => Err("missing port"),
        Some(port) => {
          let features = getStringArrayOrEmpty(obj, "features");
          if port < 1024 || port > 65535 then
            Err("invalid port")
          else if countDots(version) != 2 then
            Err("invalid version")
          else if listLength(features) == 0 then
            Err("features must not be empty")
          else
            Ok({
              app_name: appName,
              version: version,
              port: port,
              features: features
            })
        }
      }
    }
  }

func loadConfig(path: string) -> Result[Config, string] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(obj) => validateConfig(obj),
    Err(message) => Err(message)
  }
}

export func main() -> () ! {IO, FS} {
  writeFile(
    "app_config.json",
    "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}"
  );
  match loadConfig("app_config.json") {
    Ok(config) => println("Loaded ${config.app_name} v${config.version} on port ${config.port} with ${listLength(config.features)} features"),
    Err(message) => println(message)
  }
}

module benchmark/solution

type Tree = Leaf | Node(Tree, int, Tree)

func insert(tree: Tree, value: int) -> Tree =
  match tree {
    Leaf => Node(Leaf, value, Leaf),
    Node(left, current, right) =>
      if value < current then Node(insert(left, value), current, right)
      else if value > current then Node(left, current, insert(right, value))
      else tree
  }

func contains(tree: Tree, value: int) -> bool =
  match tree {
    Leaf => false,
    Node(left, current, right) =>
      if value == current then true
      else if value < current then contains(left, value)
      else contains(right, value)
  }

func size(tree: Tree) -> int =
  match tree {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

func isBST(tree: Tree, lower: int, upper: int) -> bool =
  match tree {
    Leaf => true,
    Node(left, value, right) =>
      value > lower && value < upper &&
      isBST(left, lower, value) &&
      isBST(right, value, upper)
  }

func insertPreservesBST(value: int) -> bool =
  isBST(insert(Leaf, value), -999999, 999999)

func insertThenFind(value: int) -> bool =
  contains(insert(Leaf, value), value)

export func main() -> () ! {IO} {
  let tree = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(tree)));
  println(show(contains(tree, 3)));
  println(show(contains(tree, 4)));
  println(show(isBST(tree, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

