from dataclasses import dataclass
from typing import Optional


@dataclass
class Node:
    value: int
    left: "Tree"
    right: "Tree"


@dataclass
class LeafType:
    pass


Leaf = LeafType()

Tree = Optional[Node | LeafType]


def insert(tree: Tree, value: int) -> Node:
    if isinstance(tree, LeafType):
        return Node(value, Leaf, Leaf)
    if value == tree.value:
        return tree
    if value < tree.value:
        return Node(tree.value, insert(tree.left, value), tree.right)
    return Node(tree.value, tree.left, insert(tree.right, value))


def size(tree: Tree) -> int:
    if isinstance(tree, LeafType):
        return 0
    return 1 + size(tree.left) + size(tree.right)


def contains(tree: Tree, value: int) -> bool:
    if isinstance(tree, LeafType):
        return False
    if value == tree.value:
        return True
    if value < tree.value:
        return contains(tree.left, value)
    return contains(tree.right, value)


def isBST(tree: Tree, lo: int, hi: int) -> bool:
    if isinstance(tree, LeafType):
        return True
    if tree.value <= lo or tree.value >= hi:
        return False
    return isBST(tree.left, lo, tree.value) and isBST(tree.right, tree.value, hi)


def insertPreservesBST(value: int) -> bool:
    tree = insert(Leaf, value)
    return isBST(tree, -999999, 999999)


def insertThenFind(value: int) -> bool:
    tree = insert(Leaf, value)
    return contains(tree, value)


def main() -> None:
    t = insert(insert(insert(Leaf, 5), 3), 7)
    print(size(t))
    print(contains(t, 3))
    print(contains(t, 4))
    print(isBST(t, -999999, 999999))
    print(insertPreservesBST(42))
    print(insertThenFind(42))


if __name__ == "__main__":
    main()

