def encode(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 1
    prev = s[0]
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(f"{count}{prev}")
            prev = c
            count = 1
    result.append(f"{count}{prev}")
    return "".join(result)


def decode(s: str) -> str:
    result = []
    i = 0
    while i < len(s):
        num_start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        count = int(s[num_start:i])
        result.append(s[i] * count)
        i += 1
    return "".join(result)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def singleCharEncode(s: str) -> bool:
    return encode(s) == f"1{s}"


def main() -> None:
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
    print(singleCharEncode("q"))


if __name__ == "__main__":
    main()

