_VALUES = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
]


def toRoman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError(f"number out of range (1-3999): {n}")
    parts: list[str] = []
    for value, symbol in _VALUES:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


def fromRoman(s: str) -> int:
    if not s:
        raise ValueError("empty Roman numeral")
    index = 0
    total = 0
    for value, symbol in _VALUES:
        length = len(symbol)
        while s[index:index + length] == symbol:
            total += value
            index += length
    if index != len(s):
        raise ValueError(f"invalid Roman numeral: {s!r}")
    return total


def roundtrip(n: int) -> bool:
    return fromRoman(toRoman(n)) == n


def distinctEncoding(a: int, b: int) -> bool:
    if a == b:
        raise ValueError("values must be distinct for distinct-encoding proof")
    return toRoman(a) != toRoman(b)


def main() -> None:
    print(toRoman(1994))
    print(toRoman(58))
    print(toRoman(3999))
    print(fromRoman("MCMXCIV"))
    print(fromRoman("LVIII"))
    print(roundtrip(2024))
    print(distinctEncoding(4, 6))


if __name__ == "__main__":
    main()

