from __future__ import annotations
from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class SNil:
    pass


@dataclass(frozen=True)
class SCons:
    head: int
    tail: SSet


SSet = Union[SNil, SCons]


def sMerge(a: SSet, b: SSet) -> SSet:
    match a, b:
        case SNil(), _:
            return b
        case _, SNil():
            return a
        case SCons(h1, t1), SCons(h2, t2):
            if h1 < h2:
                return SCons(h1, sMerge(t1, b))
            elif h1 > h2:
                return SCons(h2, sMerge(a, t2))
            else:
                return SCons(h1, sMerge(t1, t2))


def sIntersect(a: SSet, b: SSet) -> SSet:
    match a, b:
        case SNil(), _:
            return SNil()
        case _, SNil():
            return SNil()
        case SCons(h1, t1), SCons(h2, t2):
            if h1 < h2:
                return sIntersect(t1, b)
            elif h1 > h2:
                return sIntersect(a, t2)
            else:
                return SCons(h1, sIntersect(t1, t2))


def sLength(s: SSet) -> int:
    match s:
        case SNil():
            return 0
        case SCons(_, t):
            return 1 + sLength(t)


def toStr(s: SSet) -> str:
    elements = []
    while isinstance(s, SCons):
        elements.append(str(s.head))
        s = s.tail
    return "{" + ", ".join(elements) + "}"


def isSorted(s: SSet) -> bool:
    prev = None
    while isinstance(s, SCons):
        if prev is not None and s.head <= prev:
            return False
        prev = s.head
        s = s.tail
    return True


def mergePreservesSorted(a: SSet, b: SSet) -> bool:
    return isSorted(sMerge(a, b))


def inclusionExclusion(a: SSet, b: SSet) -> bool:
    union = sMerge(a, b)
    intersection = sIntersect(a, b)
    return sLength(union) + sLength(intersection) == sLength(a) + sLength(b)


def main():
    a = SCons(1, SCons(3, SCons(5, SNil())))
    b = SCons(2, SCons(3, SCons(4, SNil())))

    print(toStr(sMerge(a, b)))
    print(toStr(sIntersect(a, b)))
    print(sLength(sMerge(a, b)))
    print(isSorted(sMerge(a, b)))
    print(mergePreservesSorted(a, b))
    print(inclusionExclusion(a, b))


if __name__ == "__main__":
    main()

