from pathlib import Path


def create_csv_file(filename: str) -> None:
    content = """name,age,email
Alice,30,alice@example.com
Bob,25,bob@example.com
Carol,35,carol@example.com
"""
    Path(filename).write_text(content)


def is_valid_row(row: dict) -> bool:
    try:
        age = int(row["age"])
    except (ValueError, TypeError):
        return False
    if age <= 0:
        return False
    if "@" not in row.get("email", ""):
        return False
    return True


def parse_and_validate_csv(filename: str) -> list[dict]:
    valid_rows = []
    with open(filename, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if is_valid_row(row):
                valid_rows.append({
                    "name": row["name"],
                    "age": int(row["age"]),
                    "email": row["email"],
                })
    return valid_rows


def write_json(data: list[dict], filename: str) -> None:
    with open(filename, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)


def main() -> None:
    csv_filename = "users.csv"
    json_filename = "users.json"

    create_csv_file(csv_filename)
    valid_rows = parse_and_validate_csv(csv_filename)
    write_json(valid_rows, json_filename)

    print(f"Converted {len(valid_rows)} valid rows to {json_filename}")


