UNIVERSE_A = {
    ("app", 1): [("lib", 1, 3), ("util", 3, 3)],
    ("lib", 3): [("core", 3, 3)],
    ("lib", 2): [("core", 1, 2)],
    ("lib", 1): [],
    ("util", 3): [("core", 1, 1)],
    ("core", 3): [],
    ("core", 2): [],
    ("core", 1): [],
}

UNIVERSE_B = {
    ("app", 1): [("x", 1, 1), ("y", 1, 1)],
    ("x", 1): [("core", 1, 1)],
    ("y", 1): [("core", 2, 2)],
    ("core", 2): [],
    ("core", 1): [],
}


def available_versions(universe):
    versions = {}
    for (pkg, ver) in universe:
        versions.setdefault(pkg, []).append(ver)
    for pkg in versions:
        versions[pkg].sort(reverse=True)
    return versions


def resolve(universe):
    versions = available_versions(universe)

    def backtrack(assignment, worklist):
        if not worklist:
            return dict(assignment)
        dep_name, lo, hi = worklist[0]
        rest = worklist[1:]
        if dep_name in assignment:
            v = assignment[dep_name]
            if lo <= v <= hi:
                return backtrack(assignment, rest)
            return None
        for candidate in versions.get(dep_name, []):
            if not (lo <= candidate <= hi):
                continue
            assignment[dep_name] = candidate
            new_reqs = list(universe.get((dep_name, candidate), []))
            result = backtrack(assignment, new_reqs + rest)
            if result is not None:
                return result
            del assignment[dep_name]
        return None

    assignment = {"app": 1}
    initial = list(universe[("app", 1)])
    return backtrack(assignment, initial)


def main():
    for universe in (UNIVERSE_A, UNIVERSE_B):
        result = resolve(universe)
        if result is None:
            print("conflict")
        else:
            print("resolved")
            for name in sorted(result):
                print(f"{name}={result[name]}")


if __name__ == "__main__":
    main()

