module benchmark/solution

import std/xml (XmlNode, parse, findAll, findFirst, getText, getAttr, getChildren, getTag)
import std/string (contains, substring, find, length as strLength, startsWith, stringToInt)
import std/list (length as listLength, map)
import std/option (Some, None)
import docparse/types/document (Block, TextBlock, HeadingBlock, ListBlock, TableBlock, TableCell, simpleCell, mkTable, DocMetadata, emptyMetadata)
import docparse/services/zip_extract (readDocxContent)

export func parseDocx(filepath: string) -> [Block] ! {FS} {
  let xml = readDocxContent(filepath);
  match parse(xml) {
    Ok(root) => extractBodyBlocks(root),
    Err(_) => []
  }
}

export pure func extractBodyBlocks(root: XmlNode) -> [Block] =
  match findFirst(root, "w:body") {
    Some(body) => parseBodyChildren(body),
    None => []
  }

pure func parseBodyChildren(body: XmlNode) -> [Block] =
  let children = getChildren(body) in
  parseBodyChildrenList(children)

pure func parseBodyChildrenList(children: [XmlNode]) -> [Block] =
  match children {
    [] => [],
    child :: rest =>
      let tag = getTag(child) in
      let blocks = if tag == "w:p" then [parseParagraph(child)]
        else if tag == "w:tbl" then [parseTable(child)]
        else [] in
      blocks ++ parseBodyChildrenList(rest)
  }

pure func parseParagraph(p: XmlNode) -> Block =
  let pPr = findFirst(p, "w:pPr") in
  let style = extractParagraphStyle(pPr) in
  let text = extractParagraphText(p) in
  if isHeadingStyle(style) then
    let level = extractHeadingLevel(style) in
    HeadingBlock({text: text, level: level})
  else if isListStyle(pPr) then
    ListBlock({items: [text], ordered: false})
  else
    TextBlock({text: text, style: style, level: 0})

pure func extractParagraphStyle(pPr: Option[XmlNode]) -> string =
  match pPr {
    Some(pr) =>
      match findFirst(pr, "w:pStyle") {
        Some(pstyle) =>
          match getAttr(pstyle, "w:val") {
            Some(val) => val,
            None => ""
          },
        None => ""
      },
    None => ""
  }

pure func isHeadingStyle(style: string) -> bool =
  contains(style, "Heading")

pure func isListStyle(pPr: Option[XmlNode]) -> bool =
  match pPr {
    Some(pr) =>
      let numPr = findFirst(pr, "w:numPr") in
      match numPr {
        Some(_) => true,
        None => false
      },
    None => false
  }

pure func extractHeadingLevel(style: string) -> int =
  let idx = find(style, "Heading") in
  if idx >= 0 then
    let numPart = substring(style, idx + 7, strLength(style)) in
    match stringToInt(numPart) {
      Some(n) => n,
      None => 1
    }
  else
    1

pure func extractParagraphText(p: XmlNode) -> string =
  let runs = findAll(p, "w:r") in
  concatRunTexts(runs)

pure func concatRunTexts(runs: [XmlNode]) -> string =
  match runs {
    [] => "",
    r :: rest =>
      let text = extractRunText(r) in
      let moreText = concatRunTexts(rest) in
      "${text}${moreText}"
  }

pure func extractRunText(r: XmlNode) -> string =
  match findFirst(r, "w:t") {
    Some(t) => getText(t),
    None => ""
  }

pure func parseTable(tbl: XmlNode) -> Block =
  let rows = findAll(tbl, "w:tr") in
  let result = separateHeaderRows(rows) in
  mkTable(result.dataRows, result.headerRow)

type TableParseResult = {headerRow: [TableCell], dataRows: [[TableCell]]}

pure func separateHeaderRows(rows: [XmlNode]) -> TableParseResult =
  match rows {
    [] => {headerRow: [], dataRows: []},
    firstRow :: restRows =>
      let headerCells = parseTableCellList(findAll(firstRow, "w:tc")) in
      let dataRows = parseTableRows(restRows) in
      {headerRow: headerCells, dataRows: dataRows}
  }

pure func isHeaderRow(row: XmlNode) -> bool =
  match findFirst(row, "w:trPr") {
    Some(trPr) =>
      match findFirst(trPr, "w:tblHeader") {
        Some(_) => true,
        None => false
      },
    None => false
  }

pure func parseTableCellList(cells: [XmlNode]) -> [TableCell] =
  match cells {
    [] => [],
    cell :: rest =>
      let text = extractTableCellText(cell) in
      let tcCell = simpleCell(text) in
      tcCell :: parseTableCellList(rest)
  }

pure func parseTableRows(rows: [XmlNode]) -> [[TableCell]] =
  match rows {
    [] => [],
    row :: rest =>
      let cells = findAll(row, "w:tc") in
      let rowCells = parseTableCells(cells) in
      rowCells :: parseTableRows(rest)
  }

pure func parseTableCells(cells: [XmlNode]) -> [TableCell] =
  match cells {
    [] => [],
    cell :: rest =>
      let text = extractTableCellText(cell) in
      let tcCell = simpleCell(text) in
      tcCell :: parseTableCells(rest)
  }

pure func extractTableCellText(tc: XmlNode) -> string =
  let paragraphs = findAll(tc, "w:p") in
  concatCellParagraphs(paragraphs)

pure func concatCellParagraphs(paras: [XmlNode]) -> string =
  match paras {
    [] => "",
    p :: rest =>
      let text = extractParagraphText(p) in
      let moreText = concatCellParagraphs(rest) in
      if strLength(text) > 0 && strLength(moreText) > 0 then
        "${text} ${moreText}"
      else if strLength(text) > 0 then
        text
      else
