from typing import Annotated
from functools import wraps


class IO:
    """Marker for IO side effects."""
    pass


class FS:
    """Marker for filesystem side effects."""
    pass


def with_effects(*effects):
    """Decorator to explicitly track a function's effects at runtime."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        wrapper.effects = effects
        return wrapper
    return decorator


def get_effects(func):
    """Retrieve the effects tracked for a function."""
    return getattr(func, "effects", ())


# Pure function — no side effects, no effect annotations
def computeSum(a: int, b: int) -> int:
    return a + b


# IO effect only — marked both in type signature and at runtime
@with_effects(IO)
def printSum(a: int, b: int) -> Annotated[None, IO]:
    result = computeSum(a, b)
    print(f"Sum: {result}")


# IO and FS effects — marked with both effect markers
@with_effects(IO, FS)
def logToFile(filename: str, message: str) -> Annotated[None, IO, FS]:
    with open(filename, "w") as f:
        f.write(message)


def main():
    result = computeSum(10, 20)
    printSum(10, 20)
    logToFile("output.txt", "Sum was 30")
    print("Done")


if __name__ == "__main__":
