def parse_expression(s):
    pos = [0]

    def peek():
        return s[pos[0]] if pos[0] < len(s) else "\0"

    def expr():
        left = term()
        while peek() in "+-":
            op = s[pos[0]]
            pos[0] += 1
            left = "(%s%s%s)" % (left, op, term())
        return left

    def term():
        left = unary()
        while peek() in "*/":
            op = s[pos[0]]
            pos[0] += 1
            left = "(%s%s%s)" % (left, op, unary())
        return left

    def unary():
        if peek() == "-":
            pos[0] += 1
            return "(-%s)" % unary()
        return power()

    def power():
        base = atom()
        if peek() == "^":
            pos[0] += 1
            return "(%s^%s)" % (base, unary())
        return base

    def atom():
        if peek() == "(":
            pos[0] += 1
            e = expr()
            pos[0] += 1
            return e
        j = pos[0]
        while j < len(s) and s[j].isdigit():
            j += 1
        num = s[pos[0]:j]
        pos[0] = j
        return num

    return expr()


