def glob_match(pat, s):
    toks = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == "*":
            toks.append(("*", None)); i += 1
        elif c == "?":
            toks.append(("?", None)); i += 1
        elif c == "[":
            i += 1
            neg = pat[i] == "!"
            if neg:
                i += 1
            chars = set()
            while pat[i] != "]":
                if i + 2 < len(pat) and pat[i + 1] == "-" and pat[i + 2] != "]":
                    for o in range(ord(pat[i]), ord(pat[i + 2]) + 1):
                        chars.add(chr(o))
                    i += 3
                else:
                    chars.add(pat[i])
                    i += 1
            i += 1
            toks.append(("set", (frozenset(chars), neg)))
        else:
            toks.append(("lit", c)); i += 1

    @lru_cache(maxsize=None)
    def m(pi, si):
        if pi == len(toks):
            return si == len(s)
        kind, val = toks[pi]
        if kind == "*":
            if m(pi + 1, si):
                return True
            if si < len(s) and s[si] != "/" and m(pi, si + 1):
                return True
            return False
        if si >= len(s):
            return False
        c = s[si]
        if kind == "?":
            ok = c != "/"
        elif kind == "lit":
            ok = c == val
        else:
            chars, neg = val
            if neg:
                ok = c != "/" and c not in chars
            else:
                ok = c in chars
        return ok and m(pi + 1, si + 1)

    return 1 if m(0, 0) else 0


