def render_emphasis(s):
    punct = set(string.punctuation)

    def ws(c):
        return c == " " or c.isspace()

    segs = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == "*":
            j = i
            while j < n and s[j] == "*":
                j += 1
            prev = s[i - 1] if i > 0 else " "
            nxt = s[j] if j < n else " "
            left = (not ws(nxt)) and (nxt not in punct or ws(prev) or prev in punct)
            right = (not ws(prev)) and (prev not in punct or ws(nxt) or nxt in punct)
            run = {"orig": j - i, "rem": j - i, "open": left, "close": right,
                   "om": [], "cm": []}
            segs.append(("run", run))
            i = j
        else:
            j = i
            while j < n and s[j] != "*":
                j += 1
            segs.append(("text", s[i:j]))
            i = j

    runs = [r for k, r in segs if k == "run"]
    cursor = 0
    while cursor < len(runs):
        cl = runs[cursor]
        if not cl["close"] or cl["rem"] == 0:
            cursor += 1
            continue
        oi = -1
        for k in range(cursor - 1, -1, -1):
            op = runs[k]
            if op["rem"] > 0 and op["open"]:
                if ((cl["open"] or op["close"])
                        and (cl["orig"] + op["orig"]) % 3 == 0
                        and not (cl["orig"] % 3 == 0 and op["orig"] % 3 == 0)):
                    continue
                oi = k
                break
        if oi < 0:
            if not cl["open"]:
                del runs[cursor]
            else:
                cursor += 1
            continue
        op = runs[oi]
        if op["rem"] >= 2 and cl["rem"] >= 2:
            use, tag = 2, "strong"
        else:
            use, tag = 1, "em"
        op["rem"] -= use
        cl["rem"] -= use
        op["om"].append(tag)
        cl["cm"].append(tag)
        del runs[oi + 1:cursor]
        cursor = oi + 1
        if op["rem"] == 0:
            del runs[oi]
            cursor -= 1
        if cl["rem"] == 0:
            del runs[cursor]

    out = []
    for k, v in segs:
        if k == "text":
            out.append(v)
        else:
            out.append("".join("</%s>" % t for t in v["cm"]))
            out.append("*" * v["rem"])
            out.append("".join("<%s>" % t for t in reversed(v["om"])))
    return "".join(out)


