def resolve_universe(uni):
    def rec(assign, wl):
        if not wl:
            return dict(assign)
        dep, lo, hi = wl[0]
        rest = wl[1:]
        if dep in assign:
            if lo <= assign[dep] <= hi:
                return rec(assign, rest)
            return None
        cands = sorted([v for v in uni.get(dep, {}) if lo <= v <= hi],
                       reverse=True)
        for v in cands:
            assign[dep] = v
            r = rec(assign, list(uni[dep][v]) + rest)
            if r is not None:
                return r
            del assign[dep]
        return None

    res = rec({"app": 11}, list(uni["app"][11]))
