import sys
from functools import lru_cache


def parse_pattern(pattern):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            tokens.append(('star',))
            i += 1
        elif c == '?':
            tokens.append(('question',))
            i += 1
        elif c == '[':
            j = i + 1
            negative = False
            if j < n and pattern[j] == '!':
                negative = True
                j += 1
            items = []
            while j < n and pattern[j] != ']':
                if j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    items.append(('range', pattern[j], pattern[j + 2]))
                    j += 3
                else:
                    items.append(('char', pattern[j]))
                    j += 1
            tokens.append(('class', negative, tuple(items)))
            i = j + 1
        else:
            tokens.append(('literal', c))
            i += 1
    return tokens


def char_in_class(ch, negative, items):
    in_set = False
    for item in items:
        if item[0] == 'char':
            if ch == item[1]:
                in_set = True
                break
        else:
            _, lo, hi = item
            if lo <= ch <= hi:
                in_set = True
                break
    if negative:
        if ch == '/':
            return False
        return not in_set
    return in_set


def match(pattern, string):
    tokens = parse_pattern(pattern)
    n = len(string)

    @lru_cache(maxsize=None)
    def rec(ti, si):
        if ti == len(tokens):
            return si == n
        tok = tokens[ti]
        kind = tok[0]
        if kind == 'star':
            if rec(ti + 1, si):
                return True
            if si < n and string[si] != '/':
                if rec(ti, si + 1):
                    return True
            return False
        if kind == 'question':
            if si < n and string[si] != '/':
                return rec(ti + 1, si + 1)
            return False
        if kind == 'class':
            _, negative, items = tok
            if si < n and char_in_class(string[si], negative, items):
                return rec(ti + 1, si + 1)
            return False
        if kind == 'literal':
            if si < n and string[si] == tok[1]:
                return rec(ti + 1, si + 1)
            return False
        return False

    return rec(0, 0)


