module benchmark/solution

import std/io (println)

export func main() -> () ! {IO} {
  -- Base contract
  -- M1: deadline 10, price 10000
  -- M2: deadline 40, price 20000
  -- M3: deadline 70, price 15000

  -- Apply amendment day 30: M2 price -> 22000
  let m1_price0 = 10000;
  let m2_price0 = 22000;
  let m3_price0 = 15000;

  let m1_dl0 = 10;
  let m2_dl0 = 40;
  let m3_dl0 = 70;

  -- Force majeure window [38,44] declared day 35.
  -- window length = 44-38+1 = 7
  -- Applies to deadlines within [38,44] belonging to undelivered milestones.
  -- At day 35: M1 delivered (day 8). M2 not delivered, M3 not delivered.
  -- M2 deadline 40 in [38,44] -> extended by 7 -> 47
  -- M3 deadline 70 not in window -> unchanged 70
  let m1_dl = m1_dl0;
  let m2_dl = m2_dl0 + 7;  -- 47
  let m3_dl = m3_dl0;

  let m1_price = m1_price0;
  let m2_price = m2_price0;
  let m3_price = m3_price0;

  -- Deliveries:
  -- M1 delivered day 8
  -- M2 delivered day 50
  -- M3 never delivered (cancelled at termination day 96)

  -- helper for penalty (cap 4000)
  let penaltyOf = \lateDays. {
    let raw = if lateDays > 0 then lateDays * 200 else 0;
    if raw > 4000 then 4000 else raw
  };

  -- helper for interest: price * (days_late/10 floored) / 100 floored
  let interestOf = \price. \daysLate. {
    let periods = if daysLate > 0 then daysLate / 10 else 0;
    (price * periods) / 100
  };

  -- ===== M1 delivery =====
  -- delivered day 8, effective deadline 10 -> late = max(0, 8-10)=0
  let m1_deliv_late = if 8 > m1_dl then 8 - m1_dl else 0;
  let m1_deliv_penalty = penaltyOf(m1_deliv_late);

  -- ===== M1 payment =====
  -- payment due = delivery day + 10 = 8 + 10 = 18
  -- Client pays M1 in full day 41. days_late = 41 - 18 = 23
  let m1_pay_due = 8 + 10;  -- 18
  let m1_pay_late = if 41 > m1_pay_due then 41 - m1_pay_due else 0;  -- 23
  let m1_pay_interest = interestOf(m1_price, m1_pay_late);
  -- periods = 23/10 = 2, interest = 10000*2/100 = 200

  -- M1-payment breach: was waived day 45.
  -- Was there a breach? payment late (paid day 41, due day 18) -> yes breach.
  -- WAIVED. Excluded from client_owes.

  -- ===== M2 delivery =====
  -- delivered day 50, effective deadline 47 -> late = 50-47 = 3
  let m2_deliv_late = if 50 > m2_dl then 50 - m2_dl else 0;  -- 3
  let m2_deliv_penalty = penaltyOf(m2_deliv_late);  -- 600

  -- ===== M2 payment =====
  -- payment due = delivery day + 10 = 50 + 10 = 60
  -- Notice of M2-payment breach day 61. cure window ends day 61+15=76.
  -- Client pays M2 in full day 74 (<= 76) -> CURED.
  -- days_late = 74 - 60 = 14
  let m2_pay_due = 50 + 10;  -- 60
  let m2_pay_late = if 74 > m2_pay_due then 74 - m2_pay_due else 0;  -- 14
  let m2_pay_interest = interestOf(m2_price, m2_pay_late);
  -- periods = 14/10 = 1, interest = 22000*1/100 = 220
  -- CURED means principal paid in cure window; interest still owed.

  -- ===== M3 delivery =====
  -- M3 never delivered. Notice of M3-delivery breach day 80.
  -- cure window ends day 80+15=95. Not delivered within window -> UNCURED.
  -- Termination day 96 valid (T=96 > 95).
  -- M3 cancelled: delivery penalty accrues from day after effective deadline
  -- (71) through T-1 = 95 inclusive. late_days = 95 - 71 + 1 = 25 days.
  -- Actually days late measured: from day after deadline through T-1.
  -- effective deadline m3_dl = 70. day after = 71. through 95 -> 95-71+1=25 days.
  let m3_deliv_late = 96 - 1 - m3_dl;  -- 95 - 70 = 25
  let m3_deliv_penalty = penaltyOf(m3_deliv_late);  -- 25*200=5000 capped 4000
  -- M3 payment CANCELLED.

  -- ===== Termination =====
  -- Valid: noticed breach not cured, not waived, cure window expired.
  -- Notices in order: M2-payment (day 61) -> cured. M3-delivery (day 80) -> uncured, window expires 95, T=96>95.
  -- First such breach = M3-delivery.
  let term_grounds = "M3-delivery";

  -- ===== Sums =====
  -- vendor_owes = sum of unwaived delivery penalties.
  -- M1 delivery penalty 0 (not waived) -> 0
  -- M2 delivery penalty 600 (not waived) -> 600
  -- M3 delivery penalty 4000 (not waived) -> 4000
  let vendor_owes = m1_deliv_penalty + m2_deliv_penalty + m3_deliv_penalty;

  -- client_owes = sum of unwaived payment interest.
  -- M1 payment interest 200 but WAIVED -> excluded.
  -- M2 payment interest 220 (not waived, cured but interest owed) -> included.
  -- M3 payment CANCELLED -> 0.
  let client_owes = m2_pay_interest;

  -- ===== Effective lines =====
  println("M1 effective: deadline=${show(m1_dl)} price=${show(m1_price)}");
  println("M2 effective: deadline=${show(m2_dl)} price=${show(m2_price)}");
  println("M3 effective: deadline=${show(m3_dl)} price=${show(m3_price)}");

  -- ===== M1 block =====
  println("M1 delivery: DELIVERED day=8 late=${show(m1_deliv_late)} penalty=${show(m1_deliv_penalty)}");
  println("M1 payment: PAID day=41 late=${show(m1_pay_late)} interest=${show(m1_pay_interest)}");
  println("M1 payment breach: WAIVED");

  -- ===== M2 block =====
  println("M2 delivery: DELIVERED day=50 late=${show(m2_deliv_late)} penalty=${show(m2_deliv_penalty)}");
  println("M2 payment: PAID day=74 late=${show(m2_pay_late)} interest=${show(m2_pay_interest)}");
  println("M2 payment breach: CURED");

  -- ===== M3 block =====
  println("M3 delivery: CANCELLED late_days=${show(m3_deliv_late)} penalty=${show(m3_deliv_penalty)}");
  println("M3 payment: CANCELLED");
  println("M3 delivery breach: UNCURED");

  -- ===== Termination =====
  println("termination: day=96 by=Client grounds=${term_grounds}");

  -- ===== Sums =====
  println("vendor_owes=${show(vendor_owes)}");
  println("client_owes=${show(client_owes)}");

  -- ===== Net =====
  let diff = if vendor_owes > client_owes then vendor_owes - client_owes else client_owes - vendor_owes;
  let netLine = if vendor_owes > client_owes then "net: Vendor pays Client ${show(diff)}"
    else if client_owes > vendor_owes then "net: Client pays Vendor ${show(diff)}"
    else "net: settled";
  println(netLine)
}

