def main():
    milestones = {}
    for name, deadline, price in [("M1", 10, 10000), ("M2", 40, 20000), ("M3", 70, 15000)]:
        milestones[name] = {
            "deadline": deadline,
            "price": price,
            "delivered_day": None,
            "paid_day": None,
            "cancelled": False,
        }

    notices = []  # (milestone, kind, notice_day)
    waivers = []  # (milestone, kind)
    termination = None  # (day, grounds) or (day, None)

    events = [
        (8, "deliver", "M1"),
        (30, "amend", "M2", 22000),
        (35, "force_majeure", 38, 44),
        (41, "pay", "M1"),
        (45, "waive", "M1", "payment"),
        (50, "deliver", "M2"),
        (61, "notice", "M2", "payment"),
        (74, "pay", "M2"),
        (80, "notice", "M3", "delivery"),
        (96, "terminate"),
    ]

    for event in events:
        day = event[0]
        etype = event[1]
        if etype == "deliver":
            milestones[event[2]]["delivered_day"] = day
        elif etype == "amend":
            milestones[event[2]]["price"] = event[3]
        elif etype == "force_majeure":
            d1, d2 = event[2], event[3]
            length = d2 - d1 + 1
            for data in milestones.values():
                if data["delivered_day"] is None and d1 <= data["deadline"] <= d2:
                    data["deadline"] += length
        elif etype == "pay":
            milestones[event[2]]["paid_day"] = day
        elif etype == "waive":
            waivers.append((event[2], event[3]))
        elif etype == "notice":
            notices.append((event[2], event[3], day))
        elif etype == "terminate":
            T = day
            grounds = None
            for m, kind, notice_day in notices:
                if T <= notice_day + 15:
                    continue
                if (m, kind) in waivers:
                    continue
                cure_end = notice_day + 15
                if kind == "payment":
                    cured = (
                        milestones[m]["paid_day"] is not None
                        and milestones[m]["paid_day"] <= cure_end
                    )
                else:
                    cured = (
                        milestones[m]["delivered_day"] is not None
                        and milestones[m]["delivered_day"] <= cure_end
                    )
                if not cured:
                    grounds = f"{m}-{kind}"
                    break
            if grounds is not None:
                termination = (T, grounds)
                for data in milestones.values():
                    if data["delivered_day"] is None:
                        data["cancelled"] = True
            else:
                termination = (T, None)

    lines = []
    for m in ["M1", "M2", "M3"]:
        data = milestones[m]
        lines.append(f"{m} effective: deadline={data['deadline']} price={data['price']}")

    vendor_owes = 0
    client_owes = 0

    for m in ["M1", "M2", "M3"]:
        data = milestones[m]
        deadline = data["deadline"]
        price = data["price"]

        delivery_penalty = 0
        if data["cancelled"]:
            T = termination[0]
            late_days = (T - 1) - deadline
            delivery_penalty = min(late_days * 200, 4000)
            lines.append(f"{m} delivery: CANCELLED late_days={late_days} penalty={delivery_penalty}")
        elif data["delivered_day"] is not None:
            d = data["delivered_day"]
            late = max(0, d - deadline)
            delivery_penalty = min(late * 200, 4000)
            lines.append(f"{m} delivery: DELIVERED day={d} late={late} penalty={delivery_penalty}")

        payment_interest = 0
        if data["cancelled"]:
            lines.append(f"{m} payment: CANCELLED")
        elif data["paid_day"] is not None:
            d = data["paid_day"]
            due_day = data["delivered_day"] + 10
            late = max(0, d - due_day)
            periods = late // 10
            payment_interest = (price * periods) // 100
            lines.append(f"{m} payment: PAID day={d} late={late} interest={payment_interest}")

        for kind in ["delivery", "payment"]:
            noticed = any(n[0] == m and n[1] == kind for n in notices)
            waived = (m, kind) in waivers
            if noticed or waived:
                if waived:
                    status = "WAIVED"
                else:
                    notice_day = next(n[2] for n in notices if n[0] == m and n[1] == kind)
                    cure_end = notice_day + 15
                    if kind == "payment":
                        status = "CURED" if (
                            data["paid_day"] is not None and data["paid_day"] <= cure_end
                        ) else "UNCURED"
                    else:
                        status = "CURED" if (
                            data["delivered_day"] is not None and data["delivered_day"] <= cure_end
                        ) else "UNCURED"
                lines.append(f"{m} {kind} breach: {status}")

        if (m, "delivery") not in waivers:
            vendor_owes += delivery_penalty
        if (m, "payment") not in waivers:
            client_owes += payment_interest

    if termination is not None and termination[1] is not None:
        lines.append(f"termination: day={termination[0]} by=Client grounds={termination[1]}")

    lines.append(f"vendor_owes={vendor_owes}")
    lines.append(f"client_owes={client_owes}")

    if vendor_owes > client_owes:
        lines.append(f"net: Vendor pays Client {vendor_owes - client_owes}")
    elif client_owes > vendor_owes:
        lines.append(f"net: Client pays Vendor {client_owes - vendor_owes}")
    else:
        lines.append("net: settled")

    print("\n".join(lines))


if __name__ == "__main__":
    main()

