module benchmark/solution

import std/list (sortBy)

type Entry = {key: int, value: int, useCount: int, lastUsed: int}
type Operation = Get(int) | Put(int, int)
type Lookup = Missing | Found(int)

func entryCount(entries: [Entry]) -> int =
  match entries {
    [] => 0,
    _ :: rest => 1 + entryCount(rest)
  }

func lookupEntry(entries: [Entry], key: int) -> Lookup =
  match entries {
    [] => Missing,
    entry :: rest =>
      if entry.key == key then Found(entry.value)
      else lookupEntry(rest, key)
  }

func containsKey(entries: [Entry], key: int) -> bool =
  match lookupEntry(entries, key) {
    Found(_) => true,
    Missing => false
  }

func useEntry(entries: [Entry], key: int, value: int, timestamp: int) -> [Entry] =
  match entries {
    [] => [],
    entry :: rest =>
      if entry.key == key then
        {entry |
          value: value,
          useCount: entry.useCount + 1,
          lastUsed: timestamp
        } :: rest
      else
        entry :: useEntry(rest, key, value, timestamp)
  }

func isBetterVictim(candidate: Entry, current: Entry) -> bool =
  candidate.useCount < current.useCount ||
  (candidate.useCount == current.useCount &&
   candidate.lastUsed < current.lastUsed)

func findVictim(entries: [Entry], current: Entry) -> Entry =
  match entries {
    [] => current,
    entry :: rest =>
      if isBetterVictim(entry, current) then
        findVictim(rest, entry)
      else
        findVictim(rest, current)
  }

func removeKey(entries: [Entry], key: int) -> [Entry] =
  match entries {
    [] => [],
    entry :: rest =>
      if entry.key == key then rest
      else entry :: removeKey(rest, key)
  }

func evictOne(entries: [Entry]) -> [Entry] =
  match entries {
    [] => [],
    entry :: rest => {
      let victim = findVictim(rest, entry);
      removeKey(entries, victim.key)
    }
  }

func putEntry(entries: [Entry], key: int, value: int, timestamp: int) -> [Entry] {
  let present = containsKey(entries, key);
  if present then
    useEntry(entries, key, value, timestamp)
  else {
    let available =
      if entryCount(entries) >= 3 then evictOne(entries) else entries;
    {key: key, value: value, useCount: 1, lastUsed: timestamp} :: available
  }
}

func process(
  operations: [Operation],
  entries: [Entry],
  timestamp: int
) -> [Entry] ! {IO} =
  match operations {
    [] => entries,
    operation :: rest =>
      match operation {
        Get(key) =>
          match lookupEntry(entries, key) {
            Missing => {
              println("-1");
              process(rest, entries, timestamp + 1)
            },
            Found(value) => {
              println(show(value));
              let updated = useEntry(entries, key, value, timestamp);
              process(rest, updated, timestamp + 1)
            }
          },
        Put(key, value) => {
          let updated = putEntry(entries, key, value, timestamp);
          process(rest, updated, timestamp + 1)
        }
      }
  }

func compareEntries(a: Entry, b: Entry) -> int = a.key - b.key

func formatEntries(entries: [Entry]) -> string =
  match entries {
    [] => "",
    entry :: rest =>
      match rest {
        [] => "${entry.key}=${entry.value}",
        _ => "${entry.key}=${entry.value},${formatEntries(rest)}"
      }
  }

export func main() -> () ! {IO} {
  let operations = [
    Put(1, 10),
    Put(2, 20),
    Put(3, 30),
    Get(1),
    Put(4, 40),
    Put(5, 50),
    Get(3),
    Get(4),
    Get(5),
    Get(1),
    Put(4, 44),
    Put(6, 60),
    Get(5),
    Get(6),
    Get(6),
    Put(7, 70),
    Get(1),
    Get(4),
    Put(8, 80),
    Get(7)
  ];
  let finalCache = process(operations, [], 1);
  let sortedCache = sortBy(compareEntries, finalCache);
  println("cache: ${formatEntries(sortedCache)}")
}

