class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache: dict[int, tuple[int, int, int]] = {}

    def get(self, key: int) -> int:
        if key not in self.cache:
            print(-1)
            return -1
        value, count, last = self.cache[key]
        print(value)
        return value

    def put(self, key: int, value: int, ts: int) -> None:
        if key in self.cache:
            _, count, _ = self.cache[key]
            self.cache[key] = (value, count + 1, ts)
            return
        if len(self.cache) >= self.capacity:
            self.evict()
        self.cache[key] = (value, 1, ts)

    def touch(self, key: int, ts: int) -> None:
        value, count, _ = self.cache[key]
        self.cache[key] = (value, count + 1, ts)

    def evict(self) -> None:
        victim = min(self.cache.keys(), key=lambda k: (self.cache[k][1], self.cache[k][2]))
        del self.cache[victim]


def process(operations):
    cache = LFUCache(3)
    ts = 0
    for op in operations:
