                cache.touch(key, ts)
            else:
                print(-1)
        else:
            _, key, value = op
            cache.put(key, value, ts)
    keys = sorted(cache.cache.keys())
    parts = [f"{k}={cache.cache[k][0]}" for k in keys]
    print("cache: " + ",".join(parts))


def main():
    process(operations)


