def merge(xs, ys):
    result = []
    i = j = 0
    while i < len(xs) and j < len(ys):
        if xs[i] <= ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1
    result.extend(xs[i:])
    result.extend(ys[j:])
    return result


def mergeSort(xs):
    if len(xs) <= 1:
        return xs
    left, right = split(xs)
    return merge(mergeSort(left), mergeSort(right))


