    right: "Expr"


@dataclass
class Let:
    name: str
    value: "Expr"
    body: "Expr"


Expr = Union[Num, Var, Add, Mul, Let]


def lookup(name: str, env: list[tuple[str, int]]) -> int:
    for var, val in env:
        if var == name:
            return val
    raise NameError(f"Unbound variable: {name}")


def eval_expr(expr: Expr, env: list[tuple[str, int]]) -> int:
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval_expr(left, env) + eval_expr(right, env)
        case Mul(left, right):
            return eval_expr(left, env) * eval_expr(right, env)
        case Let(name, value, body):
            val = eval_expr(value, env)
            return eval_expr(body, env + [(name, val)])
        case _:
            raise TypeError(f"Unknown expression: {expr}")


