    P(expr, _) => expr
  }

func parseAdd(cs: [string]) -> Parsed =
  match parseMultiply(cs) {
    P(left, rest) => parseAddTail(left, rest)
  }

func parseAddTail(left: Expr, cs: [string]) -> Parsed =
  match cs {
    [] => P(left, []),
    op :: rest =>
      if op == "+" || op == "-" then
        match parseMultiply(rest) {
          P(right, remaining) =>
            parseAddTail(Binary(left, op, right), remaining)
        }
      else
        P(left, cs)
  }

func parseMultiply(cs: [string]) -> Parsed =
  match parseUnary(cs) {
    P(left, rest) => parseMultiplyTail(left, rest)
  }

func parseMultiplyTail(left: Expr, cs: [string]) -> Parsed =
  match cs {
    [] => P(left, []),
    op :: rest =>
      if op == "*" || op == "/" then
        match parseUnary(rest) {
          P(right, remaining) =>
            parseMultiplyTail(Binary(left, op, right), remaining)
        }
      else
        P(left, cs)
  }

func parseUnary(cs: [string]) -> Parsed =
  match cs {
    "-" :: rest =>
