def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(('num', s[i:j]))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c!r} in {s!r}")
    tokens.append(('eof', None))
    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        tok = self.advance()
        if tok[0] != kind:
            raise ValueError(f"Expected {kind!r}, got {tok!r}")
        return tok

    def parse_expr(self):
        left = self.parse_mul()
        while self.peek()[0] in ('+', '-'):
            op = self.advance()[0]
            right = self.parse_mul()
            left = f"({left}{op}{right})"
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while self.peek()[0] in ('*', '/'):
            op = self.advance()[0]
            right = self.parse_unary()
            left = f"({left}{op}{right})"
        return left

    def parse_unary(self):
        if self.peek()[0] == '-':
            self.advance()
            operand = self.parse_unary()
            return f"(-{operand})"
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek()[0] == '^':
            self.advance()
            exp = self.parse_unary()
            return f"({base}^{exp})"
        return base

    def parse_atom(self):
        tok = self.peek()
        if tok[0] == 'num':
            self.advance()
            return tok[1]
        if tok[0] == '(':
            self.advance()
            inner = self.parse_expr()
            self.expect(')')
            return inner
        raise ValueError(f"Unexpected token: {tok!r}")


def fully_parenthesize(expr):
    parser = Parser(tokenize(expr))
    result = parser.parse_expr()
    if parser.peek()[0] != 'eof':
        raise ValueError(f"Trailing tokens in {expr!r}")
    return result


def main():
    expressions = [
        "-2^2",
        "2^3^2",
        "8-4-2",
        "2^-3*4",
        "--5+1",
        "-2^-2^3",
        "(1+2)*-3",
        "100-10*-2^2",
    ]
    for expr in expressions:
        print(fully_parenthesize(expr))


if __name__ == "__main__":
    main()

