def follow_copy(name, table):
    while name in table and table[name][0] == "copy":
        name = table[name][1]
    return name


def substitute_operand(operand, table):
    if operand[0] == "lit":
        return operand
    name = operand[1]
    if name not in table:
        return ("var", name)
    entry = table[name]
    if entry[0] == "const":
        return ("lit", entry[1])
    if entry[0] == "copy":
        chased = follow_copy(entry[1], table)
        if chased in table and table[chased][0] == "const":
            return ("lit", table[chased][1])
        return ("var", chased)
    return ("var", name)


def format_operand(operand):
    if operand[0] == "lit":
        return str(operand[1])
    return operand[1]


def main():
    program = [
        ("assign", "n", "input"),
        ("assign", "m", "input"),
        ("assign", "a", ("lit", 7)),
        ("assign", "a", ("binop", "-", ("var", "a"), ("lit", 7))),
        ("assign", "c", ("binop", "*", ("var", "n"), ("var", "a"))),
        ("assign", "n", ("binop", "+", ("var", "n"), ("var", "c"))),
        ("assign", "q", ("binop", "*", ("var", "m"), ("lit", 3))),
        ("assign", "e", ("binop", "*", ("var", "n"), ("lit", 7))),
        ("assign", "f", ("binop", "-", ("var", "e"), ("var", "e"))),
        ("assign", "e", ("binop", "+", ("var", "e"), ("var", "f"))),
        ("assign", "r", ("binop", "*", ("var", "e"), ("lit", 1))),
        ("return", ("var", "r")),
    ]

    # PASS 1: SSA renaming
    counter: dict[str, int] = {}
    latest: dict[str, str] = {}
    ssa_program = []

    for instr in program:
        if instr[0] == "assign":
            name = instr[1]
            rhs = instr[2]
            k = counter.get(name, 0)
            ssa_name = f"{name}.{k}"
            counter[name] = k + 1
            latest[name] = ssa_name

            if rhs == "input":
                new_rhs = "input"
            elif rhs[0] == "lit":
                new_rhs = rhs
            else:
                op = rhs[1]
                left = rhs[2]
                right = rhs[3]
                new_left = left if left[0] == "lit" else ("var", latest[left[1]])
                new_right = right if right[0] == "lit" else ("var", latest[right[1]])
                new_rhs = ("binop", op, new_left, new_right)
            ssa_program.append(("assign", ssa_name, new_rhs))
        else:
            operand = instr[1]
            new_operand = operand if operand[0] == "lit" else ("var", latest[operand[1]])
            ssa_program.append(("return", new_operand))

    # PASS 2: forward simplification
    table: dict[str, tuple] = {}
    kept: list[tuple] = []
    return_operand = None

    for instr in ssa_program:
        if instr[0] == "assign":
            name = instr[1]
            rhs = instr[2]

            if rhs == "input":
                table[name] = ("opaque",)
                kept.append((name, "input"))
                continue

            if rhs[0] == "lit":
                table[name] = ("const", rhs[1])
                continue

            op = rhs[1]
            left = substitute_operand(rhs[2], table)
            right = substitute_operand(rhs[3], table)

            if left[0] == "lit" and right[0] == "lit":
                if op == "+":
                    table[name] = ("const", left[1] + right[1])
                elif op == "-":
                    table[name] = ("const", left[1] - right[1])
                elif op == "*":
                    table[name] = ("const", left[1] * right[1])
                continue

            if op == "-" and left[0] == "var" and right[0] == "var" and left[1] == right[1]:
                table[name] = ("const", 0)
                continue

            if op == "*":
                if (left[0] == "lit" and left[1] == 0) or (right[0] == "lit" and right[1] == 0):
                    table[name] = ("const", 0)
                    continue

            if op == "*":
                if right[0] == "lit" and right[1] == 1:
                    table[name] = ("copy", left[1])
                    continue
                if left[0] == "lit" and left[1] == 1:
                    table[name] = ("copy", right[1])
                    continue

            if op == "+":
                if right[0] == "lit" and right[1] == 0:
                    table[name] = ("copy", left[1])
                    continue
                if left[0] == "lit" and left[1] == 0:
                    table[name] = ("copy", right[1])
                    continue

            if op == "-":
                if right[0] == "lit" and right[1] == 0:
                    table[name] = ("copy", left[1])
                    continue

            table[name] = ("opaque",)
            kept.append((name, ("binop", op, left, right)))
        else:
            return_operand = substitute_operand(instr[1], table)

    # PASS 3: dead code elimination
    needed: set[str] = set()
    worklist: list[str] = []

    if return_operand[0] == "var":
        worklist.append(return_operand[1])

    while worklist:
        name = worklist.pop()
        if name in needed:
            continue
        needed.add(name)
        for def_name, rhs in kept:
            if def_name != name:
                continue
            if rhs == "input":
                continue
            for opnd in (rhs[2], rhs[3]):
                if opnd[0] == "var":
                    worklist.append(opnd[1])

    for name, rhs in kept:
        if name not in needed:
            continue
        if rhs == "input":
            print(f"{name} = input")
        else:
            op = rhs[1]
            left = format_operand(rhs[2])
            right = format_operand(rhs[3])
            print(f"{name} = {left} {op} {right}")

    print(f"return {format_operand(return_operand)}")


if __name__ == "__main__":
    main()

