    current: int
    target: int


@dataclass(frozen=True)
class DoorOpen:
    floor: int
    timer: int


State = Union[Idle, Moving, DoorOpen]


@dataclass(frozen=True)
class Call:
    floor: int


@dataclass(frozen=True)
class Tick:
    pass


@dataclass(frozen=True)
class Arrive:
    pass


Event = Union[Call, Tick, Arrive]


def transition(state: State, event: Event) -> State:
    match (state, event):
        case (Idle(floor), Call(target)) if target == floor:
            return DoorOpen(floor, 3)
        case (Idle(floor), Call(target)):
            return Moving(floor, target)
        case (Moving(current, target), Tick()):
            return Moving(current, target)
        case (Moving(current, target), Arrive()):
            return DoorOpen(target, 3)
        case (DoorOpen(floor, timer), Tick()) if timer > 1:
            return DoorOpen(floor, timer - 1)
        case (DoorOpen(floor, _), Tick()):
            return Idle(floor)
        case _:
            return state


