type State = Idle | HasCredit(int) | Dispensing(int)
type Event = Insert(int) | Select(int) | DispenseDone
type Result[a, b] = Ok(a) | Err(b)

func selectItem(credit: int, code: int) -> Result[State, string] =
  match code {
    1 => if credit < 125 then Err("insufficient_funds") else Ok(Dispensing(credit - 125)),
    2 => if credit < 75 then Err("insufficient_funds") else Ok(Dispensing(credit - 75)),
    3 => if credit < 100 then Err("insufficient_funds") else Ok(Dispensing(credit - 100)),
    _ => Err("unknown_item")
  }

func step(state: State, event: Event) -> Result[State, string] =
  match (state, event) {
    (Idle, Insert(n)) => Ok(HasCredit(n)),
    (Idle, Select(_)) => Err("no_credit"),
    (Idle, DispenseDone) => Err("not_dispensing"),
    (HasCredit(c), Insert(n)) => Ok(HasCredit(c + n)),
    (HasCredit(c), Select(code)) => selectItem(c, code),
    (HasCredit(_), DispenseDone) => Err("not_dispensing"),
    (Dispensing(_), Insert(_)) => Err("busy"),
    (Dispensing(_), Select(_)) => Err("busy"),
    (Dispensing(_), DispenseDone) => Ok(Idle)
  }

func showState(state: State) -> string =
  match state {
    Idle => "IDLE",
    HasCredit(n) => "CREDIT(${n})",
    Dispensing(change) => "DISPENSING(${change})"
  }

func showResult(result: Result[State, string]) -> string =
  match result {
    Ok(state) => "ok: ${showState(state)}",
    Err(reason) => "err: ${reason}"
  }

func simulate(state: State, events: [Event]) -> () ! {IO} =
  match events {
    [] => (),
    event :: rest => {
      let result = step(state, event);
      println(showResult(result));
      match result {
        Ok(nextState) => simulate(nextState, rest),
        Err(_) => simulate(state, rest)
      }
    }
  }

