from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar("T")
E = TypeVar("E")


@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T


@dataclass(frozen=True)
class Err(Generic[E]):
    reason: E


@dataclass(frozen=True)
class Idle:
    pass


@dataclass(frozen=True)
class HasCredit:
    cents: int


@dataclass(frozen=True)
class Dispensing:
    change: int


State = Idle | HasCredit | Dispensing


@dataclass(frozen=True)
class Insert:
    cents: int


@dataclass(frozen=True)
class Select:
    code: int


@dataclass(frozen=True)
class DispenseDone:
    pass


Event = Insert | Select | DispenseDone

PRICES = {1: 125, 2: 75, 3: 100}


def step(state: State, event: Event) -> Ok[State] | Err[str]:
    match (state, event):
        case (Idle(), Insert(n)):
            return Ok(HasCredit(n))
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        case (HasCredit(c), Insert(n)):
            return Ok(HasCredit(c + n))
        case (HasCredit(c), Select(code)) if code not in PRICES:
            return Err("unknown_item")
        case (HasCredit(c), Select(code)) if c < PRICES[code]:
            return Err("insufficient_funds")
        case (HasCredit(c), Select(code)):
            return Ok(Dispensing(c - PRICES[code]))
        case (HasCredit(), DispenseDone()):
            return Err("not_dispensing")

        case (Dispensing(), Insert(_)):
            return Err("busy")
        case (Dispensing(), Select(_)):
            return Err("busy")
        case (Dispensing(), DispenseDone()):
            return Ok(Idle())


def format_result(result: Ok[State] | Err[str]) -> str:
    match result:
        case Ok(Idle()):
            return "ok: IDLE"
        case Ok(HasCredit(n)):
            return f"ok: CREDIT({n})"
        case Ok(Dispensing(ch)):
            return f"ok: DISPENSING({ch})"
        case Err(reason):
            return f"err: {reason}"


def main() -> None:
    state: State = Idle()
    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]
    for event in events:
        result = step(state, event)
        print(format_result(result))
        match result:
            case Ok(new_state):
                state = new_state
            case Err(_):
                pass


if __name__ == "__main__":
    main()

