module benchmark/solution

type Stats = {last: int, top: [int], total: int}

pure func takeN(xs: [int], n: int) -> [int] ! {} =
  if n <= 0 then []
  else match xs {
    [] => [],
    x :: rest => x :: takeN(rest, n - 1)
  }

pure func insertTop(value: int, xs: [int], limit: int) -> [int] ! {} =
  if limit <= 0 then []
  else match xs {
    [] => [value],
    x :: rest =>
      if value >= x
      then value :: takeN(xs, limit - 1)
      else x :: insertTop(value, rest, limit - 1)
  }

pure func sumList(xs: [int]) -> int ! {} =
  match xs {
    [] => 0,
    x :: rest => x + sumList(rest)
  }

pure func generate(remaining: int, current: int, top: [int], total: int) -> Stats ! {} =
  if remaining == 0 then {last: current, top: top, total: total}
  else {
    let next = (48271 * current) % 2147483647;
    let nextTop = insertTop(next, top, 10);
    let nextTotal = (total + next) % 1000000007;
    generate(remaining - 1, next, nextTop, nextTotal)
  }

export func main() -> () ! {IO} {
