type Tree = Leaf(int) | Node(Tree, int, Tree)

pure func mapTree(fn: int -> int, tree: Tree) -> Tree ! {} =
  match tree {
    Leaf(value) => Leaf(fn(value)),
    Node(left, value, right) =>
      Node(mapTree(fn, left), fn(value), mapTree(fn, right))
  }

pure func foldTree(fn: (int, int) -> int, acc: int, tree: Tree) -> int ! {} =
  match tree {
    Leaf(value) => fn(acc, value),
    Node(left, value, right) => {
      let leftAcc = foldTree(fn, acc, left);
      let nodeAcc = fn(leftAcc, value);
      foldTree(fn, nodeAcc, right)
    }
  }

pure func treeToList(tree: Tree) -> [int] ! {} =
  match tree {
    Leaf(value) => [value],
    Node(left, value, right) =>
      treeToList(left) ++ (value :: treeToList(right))
  }

pure func maxInt(a: int, b: int) -> int ! {} =
  if a >= b then a else b

pure func treeDepth(tree: Tree) -> int ! {} =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) =>
      1 + maxInt(treeDepth(left), treeDepth(right))
  }

pure func double(value: int) -> int ! {} = value * 2

pure func add(acc: int, value: int) -> int ! {} = acc + value

