import std/option (Option, Some, None)

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

pure func showType(t: Type) -> string =
  match t {
    TVar(v) => v,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(a, r) => "TFunc(${showType(a)}, ${showType(r)})"
  }

pure func lookup(var: string, subst: [(string, Type)]) -> Option[Type] =
  match subst {
    [] => None,
    (v, t) :: rest => if v == var then Some(t) else lookup(var, rest)
  }

pure func apply(subst: [(string, Type)], t: Type) -> Type =
  match t {
    TVar(v) => match lookup(v, subst) {
      Some(t2) => apply(subst, t2),
      None => TVar(v)
    },
    TInt => TInt,
    TBool => TBool,
    TFunc(a, r) => TFunc(apply(subst, a), apply(subst, r))
  }

pure func unify(t1: Type, t2: Type) -> Option[ [(string, Type)] ] =
  match (t1, t2) {
    (TInt, TInt) => Some([]),
    (TBool, TBool) => Some([]),
    (TVar(a), b) => Some([(a, b)]),
    (a, TVar(b)) => Some([(b, a)]),
    (TFunc(a1, r1), TFunc(a2, r2)) =>
      match unify(a1, a2) {
        Some(s1) =>
          match unify(apply(s1, r1), apply(s1, r2)) {
            Some(s2) => Some(s1 ++ s2),
            None => None
          },
        None => None
      },
    _ => None
  }

pure func printSubst(subst: [(string, Type)]) -> () ! {IO} =
  match subst {
    [] => (),
    (v, t) :: rest => {
      println("${v} = ${showType(t)}");
      printSubst(rest)
    }
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Some(subst) => printSubst(subst),
    None => ()
  }
}

