from __future__ import annotations
from dataclasses import dataclass


@dataclass
class TVar:
    name: str


@dataclass
class TInt:
    pass


@dataclass
class TBool:
    pass


@dataclass
class TFunc:
    arg: TVar | TInt | TBool | TFunc
    result: TVar | TInt | TBool | TFunc


Type = TVar | TInt | TBool | TFunc
Subst = list[tuple[str, Type]]


def apply(subst: Subst, t: Type) -> Type:
    if isinstance(t, (TInt, TBool)):
        return t
    if isinstance(t, TVar):
        for name, ty in subst:
            if name == t.name:
                return apply(subst, ty)
        return t
    if isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    return t


def unify(t1: Type, t2: Type) -> Subst:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        r1 = apply(s1, t1.result)
        r2 = apply(s1, t2.result)
        s2 = unify(r1, r2)
        return s1 + s2
    raise ValueError("Cannot unify types")


def format_type(t: Type) -> str:
    if isinstance(t, TInt):
        return "TInt"
    if isinstance(t, TBool):
        return "TBool"
    if isinstance(t, TVar):
        return t.name
    if isinstance(t, TFunc):
        return f"({format_type(t.arg)} -> {format_type(t.result)})"
    return str(t)


def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    subst = unify(t1, t2)
    for name, ty in subst:
        print(f"{name} = {format_type(ty)}")


if __name__ == "__main__":
    main()
